import {test,expect,type Page} from '@playwright/test'
import type {PlayerCompetitionScheduleEvent} from '../../lib/player-competition-schedule'
const origin='http://127.0.0.1:4283'
type CalendarWindow=Window&{calendarFixture:{loseWrite:boolean;fail:boolean;failAgendaReads:number;failRangeEnd:string;defer:boolean;release:()=>void;requests:{method:string;body:{action:string}}[];personal:{id:string;title:string;updatedAt:string}[];competitions:PlayerCompetitionScheduleEvent[]};refreshNavigationSession:()=>void;switchNavigationOwner:()=>void}
async function calendarScreen(page:Page,width=390){
 await page.setViewportSize({width,height:844});await page.goto(origin+'/?large=1');await page.getByRole('button',{name:'More',exact:true}).click();await page.locator('[data-app-destination="calendar"]').click();const dialog=page.getByRole('dialog',{name:'Your calendar',exact:true});await expect(dialog.locator('.cal-event')).toHaveCount(3);return dialog
}
test('Calendar: the lead card advances to later events without removing earlier dates',async({page})=>{
 const now=new Date()
 now.setHours(12,0,0,0)
 await page.clock.setFixedTime(now)
 const calendar=await calendarScreen(page)
 const highlight=calendar.locator('[data-cal-highlight]')
 const openEvent=highlight.getByRole('button',{name:'Open event',exact:true})
 await expect(openEvent).toHaveAccessibleDescription('Serve + first ball')

 now.setHours(18,30)
 await page.clock.setFixedTime(now)
 await calendar.getByRole('button',{name:'Refresh',exact:true}).click()
 await expect(openEvent).toHaveAccessibleDescription(/Riverside Rally/)
 await openEvent.press('Enter')
 await expect(calendar.getByRole('heading',{name:'Your availability',exact:true})).toBeFocused()
 await expect(calendar).toContainText('Northside Tennis Center · Court 3')
 const back=calendar.getByRole('button',{name:'Back to calendar',exact:true})
 await back.click()
 await expect(openEvent).toBeFocused()

 await openEvent.click()
 now.setHours(20,0)
 await page.clock.setFixedTime(now)
 await back.click()
 await expect(calendar.locator('.cal-event.competition')).toBeFocused()
 await expect(calendar.locator('.cal-event.coach')).toContainText('Lesson: Jordan Lee')
 await expect(calendar.locator('.cal-event')).toHaveCount(3)
})
